/* ARCHIVO GENERADO — no editar a mano.
 * Lo produce scripts/gen-chat-data.py leyendo directo el .xlsx exportado de:
 *   https://docs.google.com/spreadsheets/d/1qW_eY7m_kevph9bEiZtaN8vX7fee_PQzjTlc8Mlp2-g/edit
 * Libro usado: CallPickerChat_Usage_2026-11-23.xlsx
 *
 * El semaforo NO replica `uso_rango` de la hoja: ese campo divide mensajes
 * entre agentes contratados y produce porcentajes sin sentido de plan
 * (hasta 433,369%). Aqui se mide SALUD DE USO. Ver el .py para la regla.
 */

export type SemaforoChat = 'saludable' | 'intenso' | 'bajo' | 'sin_uso' | 'sin_medicion' | 'suspendida'

export interface ChatInbox {
  id: number | null
  nombre: string
  tipo: string | null
  proveedor: string | null
  contratado: boolean
  activo: boolean
  observado: boolean
  conversaciones: number
  mensajes: number
  mensajesCliente: number | null
  mensajesSalida: number | null
  pctCuenta: number | null
  reconciliacion: string | null
  error: string | null
}

export interface ChatCuenta {
  cid: string
  cliente: string
  cuenta: string
  cuentaId: number | null
  periodo: string
  corte: number | null
  estado: string
  semaforo: SemaforoChat
  motivos: string[]
  motivosRescate: string[]
  conversaciones: number
  mensajes: number
  mensajesCliente: number
  mensajesSalida: number
  promedioPorConv: number | null
  inboxesContratados: number | null
  inboxesObservados: number | null
  inboxesActivos: number | null
  inboxesInactivos: number | null
  bolsaMensajes: number | null
  agentes: number | null
  pctBolsa: number | null
  mensajesPrevios: number | null
  crecimientoPct: number | null
  tendencia: string | null
  tier: string | null
  respaldoPeriodo: string | null
  respaldoMensajes: number | null
  lecturaRota: boolean
  /** Lo que midieron las bandejas en ESTA misma corrida cuando la
   *  llamada de cuenta falló. `mensajes` conserva el cero del
   *  origen: esto va aparte para que el rescate sea auditable. */
  rescateMensajes: number | null
  rescateConversaciones: number | null
  rescateCliente: number | null
  rescateSalida: number | null
  rescateBandejas: number | null
  rescateBandejasTotal: number | null
  /** true = el detalle ES el total (`contracted_inboxes`).
   *  false = es un PISO: «al menos N». */
  rescateExacto: boolean
  rescateAlcance: string | null
  rescateRefPeriodo: string | null
  rescateRefPct: number | null
  /** `mensajes` si la lectura fue buena, el rescate si no. */
  mensajesEfectivos: number
  sacux: Record<string, any> | null
}

export interface ChatCliente {
  cid: string
  nombre: string
  tier: string | null
  semaforo: SemaforoChat
  motivos: string[]
  cuentas: ChatCuenta[]
  inboxes: ChatInbox[]
  inboxesRelleno: number
  mensajes: number
  conversaciones: number
  mensajesEfectivos: number
  mensajesRescatados: number
  rescateExacto: number
  rescatePiso: number
  inboxesContratados: number
  inboxesObservados: number
  contratadosMuertos: number
  sinContratoConTrafico: number
  inboxesConTrafico: number
  inboxesSinClasificar: number
  inboxesConError: number
  periodo: string
  conError: number
  sacux: Record<string, any> | null
}

